import{_ as a,c as o,o as r,ag as t}from"./chunks/framework.CQuhCYrb.js";const f=JSON.parse('{"title":"Software Defined Radios (SDRs)","description":"","frontmatter":{"title":"Software Defined Radios (SDRs)"},"headers":[],"relativePath":"radio/software-defined-radios-sdrs.md","filePath":"radio/software-defined-radios-sdrs.md","lastUpdated":null}'),i={name:"radio/software-defined-radios-sdrs.md"};function n(s,e,d,l,c,p){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="software-defined-radios-sdrs" tabindex="-1">Software Defined Radios (SDRs) <a class="header-anchor" href="#software-defined-radios-sdrs" aria-label="Permalink to &quot;Software Defined Radios (SDRs)&quot;">​</a></h1><h2 id="sdr-according-to-wikipedia" tabindex="-1">SDR, According to <a href="https://en.wikipedia.org/wiki/Software-defined_radio" target="_blank" rel="noreferrer">Wikipedia</a> <a class="header-anchor" href="#sdr-according-to-wikipedia" aria-label="Permalink to &quot;SDR, According to [Wikipedia](https://en.wikipedia.org/wiki/Software-defined_radio)&quot;">​</a></h2><blockquote><p>Software-defined radio (SDR) is a radio communication system where components that have been traditionally implemented in analog hardware (e.g., mixers, filters, amplifiers, modulators/demodulators, detectors, etc.) are instead implemented using software on a personal computer or embedded system. While the concept of SDR is not new, the rapidly evolving capabilities of digital electronics render practical many processes that were once only theoretically possible.</p></blockquote><p>A basic SDR system may consist of a personal computer with a sound card or analog-to-digital converter, preceded by some RF front end. Significant signal processing is handed over to the general-purpose processor rather than done in special-purpose hardware (electronic circuits). Such a design produces a radio that can receive and transmit widely different radio protocols (sometimes called waveforms) based solely on the software used.</p><p>Software radios have significant utility for the military and cell phone services, which must serve various changing radio protocols in real time. In the long term, proponents like the Wireless Innovation Forum expect software-defined radios to become the dominant technology in radio communications. SDRs and software-defined antennas are the enablers of cognitive radio.</p><h3 id="sdr-in-use" tabindex="-1">SDR In Use <a class="header-anchor" href="#sdr-in-use" aria-label="Permalink to &quot;SDR In Use&quot;">​</a></h3><ul><li><p>HackRF</p></li><li><p>PlutoSDR</p></li></ul><h3 id="sdr-to-start" tabindex="-1">SDR To Start <a class="header-anchor" href="#sdr-to-start" aria-label="Permalink to &quot;SDR To Start&quot;">​</a></h3><p>If you&#39;re trying to teach/learn, the PlutoSDR + Pysdr is great. If you want to learn a little about networking mixed in, it can be made to be networked. If you want to learn about FPGA a little, it can run Maia firmware and see over 50Mhz broad spectrum via FPGA/onboard web interface. Another firmware does nearly the same + adds 8-bit mode to get even more bandwidth. It can be hacked to support LTE. If you want to learn about building roots and your own firmware, you can also do that. It&#39;s a pretty extensive list, to be honest, and they&#39;re available at Mouser.</p><ul><li>Aaron</li></ul><h3 id="sdr-comparison" tabindex="-1">SDR Comparison <a class="header-anchor" href="#sdr-comparison" aria-label="Permalink to &quot;SDR Comparison&quot;">​</a></h3><p><a href="#">SDR Comparison Chart|center</a><a href="#">Comparison</a><a href="https://www.crowdsupply.com/lime-micro/limesdr#products" target="_blank" rel="noreferrer">Image Source</a></p><p><a href="#">Comparison Ant E200 vs. Pluto</a><a href="https://www.crowdsupply.com/microphase-technology/antsdr-e200" target="_blank" rel="noreferrer">Image Source</a></p><h3 id="sdr-software" tabindex="-1">SDR Software <a class="header-anchor" href="#sdr-software" aria-label="Permalink to &quot;SDR Software&quot;">​</a></h3><ul><li><p>[## References</p></li><li><p>Dillinger, Markus; Madani, Kambiz; Alonistioti, Nancy (2003). <em>Software Defined Radio: Architectures, Systems, and Functions</em>. Wiley &amp; Sons. ISBN 0-470-85164-3.</p></li><li><p>Amaral, Cristiano (2021). <em>Guia Moderno do Radioescuta</em>. Brazil: Amazon. ISBN 978-65-00-20800-9.</p></li><li><p><a href="/radio/dragonos.html">https://sourceforge.net/p/dragonos-focal/wiki/Home/ DragonOS SourceForge</a></p></li></ul>',15)])])}const m=a(i,[["render",n]]);export{f as __pageData,m as default};
